-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 40 recettes, 8 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, ph->>'page',
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', 'Wikimedia Commons', ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · Wikimedia Commons',
        true, true, 'Photo Wikimedia Commons vérifiée : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"bolani-afghan","country":"AF","original":"Bolani","title":"Bolani afghan (galettes farcies aux pommes de terre et ciboule)","en":"Afghan bolani (potato and scallion stuffed flatbread)","es":"Bolani afgano (pan plano relleno de patata y cebolleta)","desc":"Galettes fines farcies de purée de pommes de terre à la ciboule et au piment, cuites à la poêle et servies avec un chutney vert.","cat":"Cuisine de rue","diff":"medium","prep":40,"cook":25,"serv":6,"ing":[["Farine",400,"g",null],["Eau tiède",250,"ml",null],["Pommes de terre",600,"g","cuites et écrasées"],["Ciboule ou oignons verts",1,"bouquet","hachés"],["Coriandre fraîche",1,"poignée",null],["Piment vert",1,null,"haché"],["Huile",80,"ml",null],["Sel",1.5,"c. à thé",null]],"steps":["Pétrir farine, eau, 1 cuillère d’huile et une pincée de sel; laisser reposer 30 minutes.","Mélanger la purée avec ciboule, coriandre, piment et sel.","Étaler des disques très fins de pâte, garnir une moitié de farce et replier en demi-lune.","Souder les bords et aplatir légèrement.","Cuire 3 minutes par face dans une poêle bien huilée et servir avec un chutney ou du yaourt."],"photo":null},{"slug":"ashak-afghan","country":"AF","original":"Ashak","title":"Ashak afghans (raviolis au poireau, yaourt et sauce à la viande)","en":"Afghan aashak (leek dumplings with yogurt and meat sauce)","es":"Ashak afganos (raviolis de puerro con yogur y salsa de carne)","desc":"Raviolis farcis de poireau et de ciboule, nappés de yaourt à l’ail, de sauce tomate à la viande et de menthe séchée.","cat":"Pâtes farcies","diff":"hard","prep":60,"cook":30,"serv":4,"ing":[["Feuilles de pâte à wonton ou pâte maison",40,null,null],["Poireaux",2,null,"très finement hachés"],["Ciboule",1,"bouquet","hachée"],["Piment en poudre",0.5,"c. à thé",null],["Bœuf haché",300,"g",null],["Concentré de tomate",2,"c. à soupe",null],["Oignon",1,null,"haché"],["Yaourt épais",300,"g",null],["Ail",2,"gousses","écrasées"],["Menthe séchée",1,"c. à soupe",null],["Huile",4,"c. à soupe",null],["Sel",1.5,"c. à thé",null]],"steps":["Saler les poireaux et la ciboule, presser pour retirer l’eau, puis ajouter piment et un filet d’huile.","Garnir les feuilles de pâte, les plier en demi-lune et bien souder.","Cuire la viande avec l’oignon et le concentré, ajouter un peu d’eau et mijoter 20 minutes.","Mélanger le yaourt avec l’ail et le sel.","Cuire les raviolis 4 minutes à la vapeur ou à l’eau.","Étaler la moitié du yaourt sur le plat, poser les raviolis, napper de yaourt, de sauce à la viande et de menthe."],"photo":null},{"slug":"shor-nakhod-kaboul","country":"AF","place":"af-kabul","original":"Shor nakhod","title":"Shor nakhod de Kaboul (salade de pois chiches et pommes de terre à la coriandre)","en":"Kabul shor nakhod (chickpea and potato street salad)","es":"Shor nakhod de Kabul (ensalada callejera de garbanzos y patata)","desc":"Pois chiches et pommes de terre servis dans un bouillon vinaigré à la coriandre et au piment, en-cas de rue populaire de Kaboul.","cat":"Cuisine de rue","diff":"easy","prep":15,"cook":60,"serv":4,"ing":[["Pois chiches secs",250,"g","trempés une nuit"],["Pommes de terre",3,null,"en cubes"],["Oignon rouge",1,null,"en fines lamelles"],["Coriandre fraîche",1,"bouquet",null],["Piment vert",2,null,null],["Ail",2,"gousses",null],["Vinaigre blanc",80,"ml",null],["Sel",1.5,"c. à thé",null]],"steps":["Cuire les pois chiches 50 minutes dans l’eau salée.","Cuire les pommes de terre 15 minutes à part.","Mixer coriandre, piment, ail, vinaigre, sel et un peu d’eau en chutney liquide.","Mélanger pois chiches, pommes de terre et un peu d’eau de cuisson.","Servir en bols arrosés de chutney et garnis d’oignon rouge."],"photo":null},{"slug":"ghapama-armenienne","country":"AM","original":"Ghapama","title":"Ghapama arménienne (potiron farci au riz, fruits secs et miel)","en":"Armenian ghapama (pumpkin stuffed with rice and dried fruit)","es":"Ghapama armenia (calabaza rellena de arroz y frutos secos)","desc":"Potiron entier farci de riz, abricots secs, raisins, pruneaux, noix, cannelle et miel, cuit au four pour les fêtes d’hiver.","cat":"Plat principal","diff":"medium","prep":30,"cook":120,"serv":6,"ing":[["Potiron entier (2–3 kg)",1,null,null],["Riz",250,"g","précuit 10 minutes"],["Abricots secs",80,"g","hachés"],["Raisins secs",60,"g",null],["Pruneaux",60,"g","hachés"],["Noix",60,"g","concassées"],["Beurre fondu",80,"g",null],["Miel",4,"c. à soupe",null],["Cannelle",1,"c. à thé",null],["Sel",1,"pincée",null]],"steps":["Découper un chapeau dans le potiron et retirer les graines.","Mélanger le riz précuit, les fruits secs, les noix, la cannelle, le beurre, le miel et le sel.","Remplir le potiron et remettre le chapeau.","Cuire 1 h 30 à 2 heures à 180 °C jusqu’à ce que la chair soit tendre.","Découper en tranches à table et servir."],"photo":null},{"slug":"harissa-armenienne","country":"AM","original":"Harissa (Arménie)","title":"Harissa arménienne (bouillie de blé et de poulet)","en":"Armenian harissa (wheat and chicken porridge)","es":"Harissa armenia (gachas de trigo y pollo)","desc":"Bouillie de blé et de poulet battue longuement jusqu’à devenir lisse, plat de fête et de partage en Arménie.","cat":"Plat principal","diff":"medium","prep":15,"cook":240,"serv":6,"ing":[["Blé décortiqué",400,"g","trempé une nuit"],["Poulet",1.2,"kg",null],["Eau",3,"l",null],["Beurre",80,"g",null],["Cumin",1,"c. à thé","facultatif"],["Sel",2,"c. à thé",null]],"steps":["Cuire le poulet dans l’eau salée 1 heure; retirer les os et effilocher la viande.","Ajouter le blé au bouillon et cuire 2 heures à feu très doux en remuant souvent.","Remettre le poulet et battre énergiquement avec une cuillère en bois jusqu’à consistance lisse.","Cuire encore 30 minutes en remuant.","Servir arrosé de beurre fondu et de cumin."],"photo":null},{"slug":"gata-armenienne","country":"AM","original":"Gata","title":"Gata arménienne (brioche feuilletée fourrée au beurre sucré)","en":"Armenian gata (sweet buttery pastry)","es":"Gata armenia (pan dulce hojaldrado)","desc":"Pâtisserie arménienne à la pâte levée fourrée d’un mélange sablé de beurre, farine et sucre (khoriz), dorée et décorée.","cat":"Dessert","diff":"medium","prep":40,"cook":35,"serv":10,"ing":[["Farine",450,"g","pour la pâte"],["Beurre",150,"g","pour la pâte"],["Yaourt",150,"g",null],["Levure sèche",7,"g",null],["Œuf",1,null,null],["Farine (khoriz)",150,"g",null],["Beurre (khoriz)",120,"g","mou"],["Sucre",150,"g",null],["Vanille",1,"c. à thé",null],["Jaune d’œuf",1,null,"pour dorer"]],"steps":["Pétrir farine, beurre, yaourt, levure et œuf; laisser reposer 1 heure au frais.","Mélanger du bout des doigts farine, beurre mou, sucre et vanille pour le khoriz.","Étaler la pâte en rectangle, couvrir de khoriz et rouler serré.","Aplatir le rouleau, couper en tronçons et décorer à la fourchette.","Dorer au jaune et cuire 30 à 35 minutes à 180 °C."],"photo":null},{"slug":"dushbara-azerbaidjan","country":"AZ","original":"Düşbərə","title":"Düşbərə azerbaïdjanais (mini-raviolis d’agneau en bouillon)","en":"Azerbaijani dushbara (tiny lamb dumpling soup)","es":"Düşbərə azerbaiyano (sopa de mini raviolis de cordero)","desc":"Minuscules raviolis d’agneau servis dans un bouillon clair, parfumés de menthe séchée et de vinaigre à l’ail.","cat":"Soupe","diff":"hard","prep":90,"cook":30,"serv":6,"ing":[["Farine",350,"g",null],["Œuf",1,null,null],["Eau",120,"ml",null],["Agneau haché",400,"g",null],["Oignon",1,null,"râpé"],["Bouillon d’agneau",2,"l",null],["Menthe séchée",2,"c. à thé",null],["Vinaigre à l’ail",3,"c. à soupe","pour servir"],["Sel et poivre",1.5,"c. à thé",null]],"steps":["Pétrir farine, œuf, eau et sel en pâte ferme; reposer 30 minutes.","Mélanger l’agneau, l’oignon, le sel et le poivre.","Étaler la pâte très finement et couper des carrés de 2 cm.","Garnir chaque carré d’une pointe de farce, plier en triangle puis joindre les pointes.","Cuire les raviolis 8 minutes dans le bouillon frémissant.","Servir avec menthe séchée et vinaigre à l’ail."],"photo":null},{"slug":"piti-sheki","country":"AZ","place":{"slug":"az-sheki","name":"Şəki (Sheki)","type":"city","lat":41.1919,"lng":47.1706,"summary":"Ville du Caucase azerbaïdjanais, patrie du piti et de la halva de Şəki."},"original":"Piti","title":"Piti de Şəki (soupe d’agneau et pois chiches en pot de terre)","en":"Sheki piti (lamb and chickpea soup in a clay pot)","es":"Piti de Sheki (sopa de cordero y garbanzos en olla de barro)","desc":"Agneau, pois chiches, châtaignes et safran cuits longuement en pot individuel; on mange d’abord le bouillon sur du pain, puis la viande.","cat":"Soupe","diff":"medium","prep":20,"cook":240,"serv":4,"ing":[["Agneau avec os",800,"g","en morceaux"],["Queue d’agneau ou gras",80,"g","facultatif"],["Pois chiches",200,"g","trempés une nuit"],["Châtaignes",150,"g","pelées"],["Oignon",1,null,"émincé"],["Prunes séchées (alycha)",8,null,null],["Safran",1,"pincée","infusé"],["Sumac",1,"c. à soupe","pour servir"],["Sel",1.5,"c. à thé",null]],"steps":["Répartir agneau, gras, pois chiches et oignon dans des pots en terre ou une cocotte.","Couvrir d’eau, saler et cuire 3 heures au four à 150 °C.","Ajouter les châtaignes, les prunes et le safran; cuire encore 1 heure.","Servir le bouillon versé sur du pain émietté saupoudré de sumac.","Écraser ensuite la viande et les pois chiches et les manger comme second plat."],"photo":null},{"slug":"lavangi-lankaran","country":"AZ","place":{"slug":"az-lankaran","name":"Lənkəran","type":"city","lat":38.7529,"lng":48.8475,"summary":"Ville subtropicale du sud de l’Azerbaïdjan, berceau du lavangi."},"original":"Ləvəngi","title":"Ləvəngi de Lənkəran (poulet farci aux noix, oignon et prunes aigres)","en":"Lankaran lavangi (chicken stuffed with walnuts and sour plums)","es":"Lavangi de Lankaran (pollo relleno de nueces y ciruelas agrias)","desc":"Poulet farci d’une pâte de noix, oignons et pâte de prunes aigres, rôti au four — spécialité de la région de Lənkəran.","cat":"Plat principal","diff":"medium","prep":30,"cook":90,"serv":6,"ing":[["Poulet entier",1.8,"kg",null],["Noix",200,"g","finement moulues"],["Oignons",2,null,"râpés et pressés"],["Pâte de prunes aigres (lavashana) ou pâte de tamarin",3,"c. à soupe",null],["Grenade (graines)",1,null,"facultatif"],["Beurre",40,"g",null],["Sel et poivre",2,"c. à thé",null]],"steps":["Mélanger noix, oignons, pâte de prunes, sel et poivre en farce épaisse.","Saler le poulet à l’intérieur et à l’extérieur.","Le farcir et le frotter avec un peu de farce et de beurre.","Rôtir 1 h 30 à 180 °C en arrosant régulièrement.","Servir avec du riz plov et des graines de grenade."],"photo":null},{"slug":"shorshe-ilish","country":"BD","original":"Shorshe ilish","title":"Shorshe ilish bangladais (hilsa à la moutarde)","en":"Bangladeshi shorshe ilish (hilsa in mustard sauce)","es":"Shorshe ilish bangladesí (sábalo en salsa de mostaza)","desc":"Darnes de hilsa, poisson national du Bangladesh, cuites dans une sauce de graines de moutarde pilées, huile de moutarde et piments verts.","cat":"Poisson","diff":"medium","prep":20,"cook":20,"serv":4,"ing":[["Hilsa ou alose",800,"g","en darnes"],["Graines de moutarde jaunes et noires",4,"c. à soupe","trempées puis pilées"],["Huile de moutarde",4,"c. à soupe",null],["Curcuma",1,"c. à thé",null],["Piments verts",4,null,"fendus"],["Nigelle",0.5,"c. à thé",null],["Sel",1.5,"c. à thé",null]],"steps":["Frotter le poisson de curcuma et de sel.","Mélanger la pâte de moutarde avec un peu d’eau, de sel et de curcuma.","Chauffer l’huile de moutarde, faire grésiller la nigelle et les piments.","Ajouter la sauce moutarde et 150 ml d’eau, porter à frémissement.","Déposer les darnes et cuire 10 à 12 minutes à couvert; arroser d’un filet d’huile de moutarde et servir avec du riz."],"photo":null},{"slug":"mezbani-gosht","country":"BD","place":{"slug":"bd-chittagong","name":"Chattogram (Chittagong)","type":"city","lat":22.3569,"lng":91.7832,"summary":"Grand port du Bangladesh, célèbre pour le mezbani, festin de bœuf épicé."},"original":"Mezbani gosht","title":"Mezbani gosht de Chattogram (curry de bœuf des festins)","en":"Chittagong mezbani beef curry","es":"Mezbani gosht de Chittagong (curry de ternera de fiesta)","desc":"Curry de bœuf très parfumé, cuit à grande échelle pour les festins mezban de Chattogram, aux épices grillées et à l’huile de moutarde.","cat":"Plat principal","diff":"medium","prep":30,"cook":120,"serv":8,"ing":[["Bœuf avec os",1.5,"kg","en morceaux"],["Oignons",4,null,"émincés"],["Ail et gingembre",4,"c. à soupe","en pâte"],["Mélange mezbani (cumin, coriandre, fenouil, cardamome, cannelle, girofle, poivre)",3,"c. à soupe","grillé et moulu"],["Piment rouge en poudre",2,"c. à thé",null],["Curcuma",1,"c. à thé",null],["Huile de moutarde",150,"ml",null],["Sel",2,"c. à thé",null]],"steps":["Mariner le bœuf avec ail, gingembre, piment, curcuma, la moitié des épices et le sel pendant 1 heure.","Faire dorer longuement les oignons dans l’huile de moutarde.","Ajouter la viande et la saisir 15 minutes à feu vif.","Couvrir et cuire 1 h 30 à feu doux avec un peu d’eau, jusqu’à ce que l’huile se sépare.","Ajouter le reste des épices 10 minutes avant la fin et servir avec du riz."],"photo":null},{"slug":"shakam-paa","country":"BT","original":"Shakam paa","title":"Shakam paa bhoutanais (bœuf séché aux piments et radis)","en":"Bhutanese shakam paa (dried beef with chilies and radish)","es":"Shakam paa butanés (ternera seca con chiles y rábano)","desc":"Bœuf séché cuit avec radis blanc, piments séchés et fromage, plat rustique des montagnes du Bhoutan.","cat":"Plat principal","diff":"easy","prep":15,"cook":40,"serv":4,"ing":[["Bœuf séché (ou bœuf en lanières)",400,"g",null],["Radis blanc (daikon)",1,null,"en bâtonnets"],["Piments rouges séchés",6,null,null],["Oignon",1,null,"émincé"],["Gingembre et ail",1,"c. à soupe","pilés"],["Fromage frais ou feta",100,"g","émietté"],["Huile",2,"c. à soupe",null],["Sel",1,"c. à thé",null]],"steps":["Faire tremper le bœuf séché 30 minutes, puis le couper en lanières.","Le faire revenir dans l’huile avec l’oignon, l’ail et le gingembre.","Ajouter radis, piments et 400 ml d’eau; cuire 25 minutes.","Ajouter le fromage et cuire 5 minutes jusqu’à ce qu’il fonde.","Saler et servir avec du riz rouge."],"photo":null},{"slug":"jasha-maru","country":"BT","original":"Jasha maru","title":"Jasha maru bhoutanais (poulet épicé à la tomate)","en":"Bhutanese jasha maru (spicy chicken stew)","es":"Jasha maru butanés (guiso picante de pollo)","desc":"Poulet haché cuit avec tomates, oignons, ail, gingembre et piments, servi avec le riz rouge du Bhoutan.","cat":"Plat principal","diff":"easy","prep":15,"cook":30,"serv":4,"ing":[["Poulet",700,"g","en petits morceaux"],["Tomates",3,null,"en dés"],["Oignon",1,null,"émincé"],["Ail",4,"gousses",null],["Gingembre",20,"g",null],["Piments verts",4,null,"fendus"],["Coriandre fraîche",1,"poignée",null],["Huile",2,"c. à soupe",null],["Sel",1,"c. à thé",null]],"steps":["Mettre le poulet dans une casserole avec 300 ml d’eau et l’huile.","Ajouter oignon, ail, gingembre et piments; cuire 15 minutes.","Ajouter les tomates et cuire 10 minutes.","Saler, parsemer de coriandre et servir avec du riz rouge."],"photo":null},{"slug":"phaksha-paa","country":"BT","original":"Phaksha paa","title":"Phaksha paa bhoutanais (porc aux radis et piments séchés)","en":"Bhutanese phaksha paa (pork with radish and dried chilies)","es":"Phaksha paa butanés (cerdo con rábano y chiles secos)","desc":"Poitrine de porc sautée avec radis, feuilles de moutarde et piments séchés, un classique de la cuisine bhoutanaise.","cat":"Plat principal","diff":"easy","prep":15,"cook":40,"serv":4,"ing":[["Poitrine de porc",600,"g","en lanières"],["Radis blanc",1,null,"en bâtonnets"],["Feuilles de moutarde ou épinards",200,"g",null],["Piments rouges séchés",8,null,null],["Gingembre et ail",1,"c. à soupe","pilés"],["Sel",1,"c. à thé",null]],"steps":["Faire fondre le porc à feu moyen jusqu’à ce qu’il rende son gras.","Ajouter l’ail, le gingembre et les piments; cuire 2 minutes.","Ajouter le radis et 300 ml d’eau; cuire 20 minutes.","Ajouter les feuilles et cuire 5 minutes.","Saler et servir avec du riz."],"photo":null},{"slug":"badrijani-nigvzit","country":"GE","original":"Badrijani nigvzit","title":"Badrijani nigvzit géorgiens (rouleaux d’aubergine aux noix)","en":"Georgian badrijani nigvzit (eggplant rolls with walnuts)","es":"Badrijani nigvzit georgianos (rollitos de berenjena con nueces)","desc":"Tranches d’aubergine frites roulées autour d’une pâte de noix à l’ail et aux épices, décorées de grenade.","cat":"Entrée","diff":"easy","prep":30,"cook":20,"serv":6,"ing":[["Aubergines",2,null,"en tranches fines dans la longueur"],["Noix",200,"g",null],["Ail",3,"gousses",null],["Coriandre fraîche",1,"bouquet",null],["Khmeli-suneli",1,"c. à thé",null],["Vinaigre de vin",1,"c. à soupe",null],["Graines de grenade",1,"poignée",null],["Huile",150,"ml",null],["Sel",1,"c. à thé",null]],"steps":["Saler les tranches d’aubergine, les frire et les égoutter.","Mixer noix, ail, coriandre, épices, vinaigre, sel et un peu d’eau en pâte.","Étaler la pâte sur chaque tranche et rouler.","Décorer de graines de grenade et servir frais."],"photo":null},{"slug":"lobio-georgien","country":"GE","original":"Lobio","title":"Lobio géorgien (haricots rouges aux herbes et épices)","en":"Georgian lobio (spiced kidney beans)","es":"Lobio georgiano (frijoles rojos con hierbas)","desc":"Haricots rouges mijotés avec oignon, coriandre, ail et épices géorgiennes, servis en pot de terre avec du pain mchadi.","cat":"Plat principal","diff":"easy","prep":15,"cook":90,"serv":4,"ing":[["Haricots rouges secs",400,"g","trempés une nuit"],["Oignons",2,null,"hachés"],["Ail",3,"gousses",null],["Coriandre fraîche",1,"bouquet",null],["Khmeli-suneli",1,"c. à thé",null],["Coriandre moulue",1,"c. à thé",null],["Piment",1,null,null],["Huile",3,"c. à soupe",null],["Sel",1.5,"c. à thé",null]],"steps":["Cuire les haricots 1 heure jusqu’à ce qu’ils soient très tendres.","Faire revenir les oignons dans l’huile.","Ajouter oignons, épices, ail, piment et sel aux haricots; écraser une partie.","Mijoter 15 minutes.","Ajouter la coriandre fraîche et servir avec du pain de maïs et des pickles."],"photo":null},{"slug":"chakhokhbili","country":"GE","original":"Chakhokhbili","title":"Chakhokhbili géorgien (poulet mijoté aux tomates et herbes)","en":"Georgian chakhokhbili (chicken stewed with tomatoes and herbs)","es":"Chakhokhbili georgiano (pollo guisado con tomate y hierbas)","desc":"Poulet doré puis mijoté avec beaucoup d’oignons, de tomates, d’ail et d’herbes fraîches.","cat":"Ragoût","diff":"easy","prep":20,"cook":60,"serv":4,"ing":[["Poulet",1.5,"kg","en morceaux"],["Oignons",3,null,"émincés"],["Tomates",6,null,"pelées et concassées"],["Ail",4,"gousses",null],["Coriandre, basilic et aneth",1,"bouquet","hachés"],["Khmeli-suneli",1,"c. à thé",null],["Piment",1,null,null],["Beurre",30,"g",null],["Sel",1.5,"c. à thé",null]],"steps":["Faire dorer le poulet à sec dans une cocotte, puis ajouter le beurre et les oignons.","Ajouter les tomates et le piment; couvrir et mijoter 40 minutes.","Ajouter l’ail, les épices et le sel; cuire 10 minutes.","Incorporer les herbes hors du feu et laisser reposer 5 minutes avant de servir."],"photo":null},{"slug":"ashlan-fu-karakol","country":"KG","place":{"slug":"kg-karakol","name":"Karakol","type":"city","lat":42.4907,"lng":78.3936,"summary":"Ville au bord du lac Issyk-Koul, célèbre pour l’ashlan-fu des Doungans."},"original":"Ashlan-fu","title":"Ashlan-fu de Karakol (soupe froide de nouilles et gelée d’amidon)","en":"Karakol ashlyan-fu (cold noodle and starch jelly soup)","es":"Ashlan-fu de Karakol (sopa fría de fideos y gelatina de almidón)","desc":"Soupe froide et vinaigrée de nouilles, gelée d’amidon, œuf et légumes, spécialité doungane de Karakol.","cat":"Soupe","diff":"medium","prep":40,"cook":30,"serv":4,"ing":[["Nouilles de blé épaisses",300,"g",null],["Amidon de pomme de terre ou de pois",60,"g","pour la gelée"],["Œufs",3,null,"en omelette fine"],["Poivrons",2,null,"en dés"],["Tomates",2,null,"en dés"],["Ail",4,"gousses",null],["Vinaigre",100,"ml",null],["Piment en poudre",1,"c. à thé",null],["Huile",3,"c. à soupe",null],["Sel",1.5,"c. à thé",null]],"steps":["La veille, cuire l’amidon avec 400 ml d’eau en remuant jusqu’à épaississement, verser dans un plat et laisser prendre; couper en lanières.","Sauter poivrons, tomates et ail dans l’huile avec le piment; ajouter 1 litre d’eau, le vinaigre et le sel; laisser refroidir.","Cuire les nouilles, les rincer à l’eau froide.","Couper l’omelette en lanières.","Assembler nouilles, gelée et omelette dans des bols et couvrir de bouillon froid."],"photo":null},{"slug":"lagman-kirghiz","country":"KG","original":"Lagman","title":"Lagman kirghiz (nouilles tirées à la main et sauce aux légumes)","en":"Kyrgyz lagman (hand-pulled noodles with meat and vegetables)","es":"Lagman kirguís (fideos estirados a mano con carne y verduras)","desc":"Nouilles tirées à la main nappées d’un sauté de bœuf, poivrons, céleri, tomates et ail, plat ouïghour-doungane très populaire au Kirghizistan.","cat":"Plat principal","diff":"hard","prep":60,"cook":30,"serv":4,"ing":[["Farine",400,"g",null],["Eau salée",220,"ml",null],["Bœuf",400,"g","en lanières"],["Poivrons",2,null,"en lanières"],["Céleri branche",2,"branches",null],["Tomates",2,null,null],["Ail",4,"gousses",null],["Sauce soja",2,"c. à soupe",null],["Huile",4,"c. à soupe",null],["Sel",1,"c. à thé",null]],"steps":["Pétrir farine et eau salée 10 minutes; reposer 1 heure enveloppée d’huile.","Rouler la pâte en boudins fins, les huiler et les étirer en nouilles longues; cuire 3 minutes à l’eau bouillante.","Saisir le bœuf dans l’huile, ajouter ail, poivrons et céleri.","Ajouter tomates, sauce soja et un peu d’eau; cuire 10 minutes.","Servir les nouilles nappées de sauce."],"photo":null},{"slug":"oromo-kirghiz","country":"KG","original":"Oromo","title":"Oromo kirghiz (roulé vapeur à la viande et au potiron)","en":"Kyrgyz oromo (steamed meat and pumpkin roll)","es":"Oromo kirguís (rollo al vapor de carne y calabaza)","desc":"Grande pâte fine roulée autour d’une farce de viande, oignon et potiron, cuite à la vapeur puis tranchée.","cat":"Plat principal","diff":"medium","prep":40,"cook":45,"serv":6,"ing":[["Farine",400,"g",null],["Eau",200,"ml",null],["Agneau ou bœuf haché",500,"g",null],["Potiron",300,"g","en petits dés"],["Oignons",2,null,"hachés"],["Cumin",1,"c. à thé",null],["Beurre",30,"g",null],["Sel et poivre",1.5,"c. à thé",null]],"steps":["Pétrir une pâte ferme avec farine, eau et sel; reposer 30 minutes.","Mélanger viande, potiron, oignons, cumin, sel et poivre.","Étaler la pâte en grand rectangle très fin, étaler la farce et parsemer de beurre.","Rouler en boudin et le disposer en spirale dans un panier vapeur huilé.","Cuire 45 minutes à la vapeur, trancher et servir avec du yaourt."],"photo":null},{"slug":"manty-kazakh","country":"KZ","original":"Manty","title":"Manty kazakhs (gros raviolis vapeur à l’agneau et oignon)","en":"Kazakh manty (steamed lamb dumplings)","es":"Manty kazajos (empanadillas al vapor de cordero)","desc":"Grands raviolis cuits à la vapeur, farcis d’agneau haché au couteau, d’oignon et de potiron, servis avec crème aigre.","cat":"Pâtes farcies","diff":"medium","prep":60,"cook":45,"serv":6,"ing":[["Farine",500,"g",null],["Eau",250,"ml",null],["Agneau",600,"g","haché au couteau"],["Oignons",3,null,"hachés"],["Potiron",200,"g","en petits dés"],["Cumin",1,"c. à thé",null],["Beurre",40,"g",null],["Crème aigre",200,"g","pour servir"],["Sel et poivre",2,"c. à thé",null]],"steps":["Pétrir farine, eau et sel; reposer 30 minutes.","Mélanger agneau, oignons, potiron, cumin, sel et poivre.","Étaler la pâte finement et découper des carrés de 12 cm.","Garnir, poser une noisette de beurre et fermer en joignant les coins.","Cuire 40 à 45 minutes à la vapeur dans une mantovarka.","Servir avec crème aigre."],"photo":null},{"slug":"sorpa-kazakh","country":"KZ","original":"Sorpa","title":"Sorpa kazakhe (bouillon de mouton aux herbes)","en":"Kazakh sorpa (mutton broth)","es":"Sorpa kazaja (caldo de cordero)","desc":"Bouillon riche de mouton servi en bol avec oignon, herbes et parfois des boulettes de pâte, compagnon du beshbarmak.","cat":"Soupe","diff":"easy","prep":10,"cook":150,"serv":6,"ing":[["Mouton avec os",1.2,"kg",null],["Oignons",2,null,null],["Carotte",1,null,null],["Pommes de terre",3,null,"en cubes"],["Laurier",2,"feuilles",null],["Aneth et persil",1,"bouquet",null],["Sel",2,"c. à thé",null]],"steps":["Couvrir la viande de 3 litres d’eau froide et porter à ébullition en écumant soigneusement.","Ajouter un oignon entier, la carotte et le laurier; mijoter 2 heures.","Ajouter les pommes de terre 20 minutes avant la fin.","Émincer le second oignon et le mettre dans les bols avec les herbes.","Verser le bouillon brûlant et servir la viande à part."],"photo":null},{"slug":"kespe-kazakh","country":"KZ","original":"Kespe","title":"Kespe kazakh (soupe de nouilles maison au bœuf)","en":"Kazakh kespe (homemade noodle soup)","es":"Kespe kazajo (sopa de fideos caseros)","desc":"Nouilles fraîches coupées au couteau dans un bouillon de bœuf aux légumes, soupe familiale kazakhe.","cat":"Soupe","diff":"medium","prep":40,"cook":60,"serv":6,"ing":[["Farine",250,"g",null],["Œuf",1,null,null],["Eau",60,"ml",null],["Bœuf",500,"g","en dés"],["Oignon",1,null,"haché"],["Carotte",1,null,"en julienne"],["Poivron",1,null,"en lanières"],["Tomate",1,null,"en dés"],["Aneth",1,"poignée",null],["Sel",2,"c. à thé",null]],"steps":["Pétrir farine, œuf, eau et sel; étaler finement et couper en nouilles.","Faire revenir bœuf, oignon et carotte, puis ajouter poivron et tomate.","Couvrir de 2 litres d’eau et mijoter 45 minutes.","Ajouter les nouilles et cuire 5 minutes.","Parsemer d’aneth et servir."],"photo":null},{"slug":"appa-sri-lankais","country":"LK","original":"Appa (hoppers)","title":"Appa sri-lankais (hoppers au lait de coco et œuf)","en":"Sri Lankan hoppers (appa) with egg","es":"Appa de Sri Lanka (crepes cuenco de coco con huevo)","desc":"Crêpes en forme de bol, croustillantes sur les bords et moelleuses au centre, à base de farine de riz fermentée et de lait de coco.","cat":"Petit-déjeuner","diff":"medium","prep":20,"cook":30,"serv":4,"ing":[["Farine de riz",250,"g",null],["Lait de coco",400,"ml",null],["Levure sèche",4,"g",null],["Sucre",1,"c. à soupe",null],["Eau tiède",150,"ml",null],["Œufs",4,null,"facultatif"],["Sel",0.5,"c. à thé",null]],"steps":["Délayer la levure et le sucre dans l’eau tiède.","Mélanger avec la farine de riz et la moitié du lait de coco; laisser fermenter 8 heures.","Ajouter le reste du lait de coco et le sel pour une pâte fluide.","Verser une louche dans une petite poêle creuse (appachatti) chaude et la faire tourner pour napper les bords.","Casser un œuf au centre si désiré, couvrir et cuire 3 minutes.","Servir avec pol sambol ou curry."],"photo":null},{"slug":"kiribath","country":"LK","original":"Kiribath","title":"Kiribath sri-lankais (riz au lait de coco du Nouvel An)","en":"Sri Lankan kiribath (coconut milk rice)","es":"Kiribath de Sri Lanka (arroz con leche de coco)","desc":"Riz cuit au lait de coco puis pressé et coupé en losanges, servi aux fêtes et au Nouvel An cinghalais avec lunu miris.","cat":"Riz","diff":"easy","prep":10,"cook":30,"serv":6,"ing":[["Riz rond blanc",400,"g",null],["Eau",750,"ml",null],["Lait de coco épais",300,"ml",null],["Sel",1,"c. à thé",null],["Oignon rouge",1,null,"pour le lunu miris"],["Piment en poudre",1,"c. à thé","pour le lunu miris"],["Citron vert",1,null,null]],"steps":["Cuire le riz dans l’eau 15 minutes jusqu’à ce qu’elle soit absorbée.","Ajouter le lait de coco et le sel; cuire 10 minutes à feu doux en remuant jusqu’à consistance crémeuse.","Étaler le riz sur un plat sur 2 cm et lisser.","Laisser tiédir et couper en losanges.","Piler oignon, piment, citron et sel pour le lunu miris et servir avec."],"photo":null},{"slug":"parippu-sri-lankais","country":"LK","original":"Parippu","title":"Parippu sri-lankais (dhal de lentilles corail au lait de coco)","en":"Sri Lankan parippu (red lentil coconut dhal)","es":"Parippu de Sri Lanka (dhal de lentejas rojas con coco)","desc":"Lentilles corail cuites au curcuma et au lait de coco, tempérées de feuilles de curry, moutarde et oignon.","cat":"Plat principal","diff":"easy","prep":10,"cook":30,"serv":4,"ing":[["Lentilles corail",250,"g","rincées"],["Lait de coco",250,"ml",null],["Curcuma",0.5,"c. à thé",null],["Oignon",1,null,"émincé"],["Ail",2,"gousses",null],["Piment vert",1,null,null],["Graines de moutarde",1,"c. à thé",null],["Feuilles de curry",10,null,null],["Huile",2,"c. à soupe",null],["Sel",1,"c. à thé",null]],"steps":["Cuire les lentilles dans 600 ml d’eau avec le curcuma et le piment 15 minutes.","Ajouter le lait de coco et le sel; cuire 5 minutes.","Faire éclater la moutarde dans l’huile, ajouter feuilles de curry, oignon et ail.","Verser cette tempérance sur les lentilles.","Servir avec du riz."],"photo":null},{"slug":"mas-riha","country":"MV","original":"Mas riha","title":"Mas riha maldivien (curry de thon au lait de coco)","en":"Maldivian mas riha (tuna curry)","es":"Mas riha maldivo (curry de atún)","desc":"Curry de thon frais aux épices, feuilles de curry et lait de coco, plat quotidien des Maldives servi avec riz ou roshi.","cat":"Poisson","diff":"easy","prep":15,"cook":30,"serv":4,"ing":[["Thon frais",600,"g","en cubes"],["Lait de coco",400,"ml",null],["Oignon",1,null,"émincé"],["Ail et gingembre",1,"c. à soupe","pilés"],["Feuilles de curry",10,null,null],["Poudre de curry maldivienne",1,"c. à soupe",null],["Piment",1,null,null],["Huile",2,"c. à soupe",null],["Sel",1,"c. à thé",null]],"steps":["Faire revenir oignon, ail, gingembre et feuilles de curry dans l’huile.","Ajouter la poudre de curry et le piment; cuire 1 minute.","Verser le lait de coco et 200 ml d’eau; mijoter 10 minutes.","Ajouter le thon et cuire 8 minutes à feu doux.","Saler et servir avec du riz ou du roshi."],"photo":null},{"slug":"masroshi","country":"MV","original":"Masroshi","title":"Masroshi maldiviens (galettes farcies au thon et coco)","en":"Maldivian masroshi (tuna and coconut stuffed flatbreads)","es":"Masroshi maldivos (panes rellenos de atún y coco)","desc":"Petites galettes farcies de thon fumé, noix de coco râpée, oignon et piment, cuites au four, en-cas du « hedhikaa » de l’après-midi.","cat":"Cuisine de rue","diff":"medium","prep":30,"cook":20,"serv":6,"ing":[["Farine",300,"g",null],["Noix de coco râpée",150,"g","dont 50 g pour la pâte"],["Thon fumé ou en conserve",200,"g","émietté"],["Oignon",1,null,"haché fin"],["Piment",1,null,"haché"],["Citron vert",1,null,"jus"],["Feuilles de curry",6,null,"hachées"],["Eau chaude",180,"ml",null],["Sel",1,"c. à thé",null]],"steps":["Mélanger thon, 100 g de coco, oignon, piment, feuilles de curry, citron et sel.","Pétrir farine, 50 g de coco, sel et eau chaude en pâte souple.","Former des boules, les aplatir et garnir de farce.","Refermer et aplatir en galettes.","Cuire 20 minutes à 200 °C ou à la poêle 4 minutes par face."],"photo":null},{"slug":"bis-keemiya","country":"MV","original":"Bis keemiya","title":"Bis keemiya maldiviens (chaussons au thon, chou et œuf)","en":"Maldivian bis keemiya (tuna and cabbage pastries)","es":"Bis keemiya maldivos (empanadillas de atún y col)","desc":"Chaussons frits farcis de chou, thon, oignon et œuf dur, version maldivienne du samoussa.","cat":"Cuisine de rue","diff":"medium","prep":40,"cook":20,"serv":6,"ing":[["Feuilles de pâte à samoussa ou pâte brisée",20,null,null],["Chou",300,"g","émincé"],["Thon en conserve",150,"g",null],["Œufs durs",3,null,"hachés"],["Oignon",1,null,"émincé"],["Curcuma",0.5,"c. à thé",null],["Huile",750,"ml","pour la friture"],["Sel",1,"c. à thé",null]],"steps":["Faire revenir l’oignon et le chou avec le curcuma 8 minutes.","Ajouter thon, œufs et sel; laisser refroidir.","Garnir la pâte et former des chaussons en demi-lune ou rectangles.","Frire 3 à 4 minutes jusqu’à ce qu’ils soient dorés.","Servir chaud avec du thé."],"photo":null},{"slug":"sel-roti","country":"NP","original":"Sel roti","title":"Sel roti népalais (anneaux de riz frits sucrés)","en":"Nepali sel roti (sweet rice doughnut rings)","es":"Sel roti nepalí (anillos de arroz fritos)","desc":"Anneaux croustillants de pâte de riz sucrée frits dans le ghee, incontournables des fêtes de Tihar et Dashain.","cat":"Dessert","diff":"medium","prep":20,"cook":30,"serv":10,"ing":[["Riz blanc",400,"g","trempé une nuit"],["Sucre",120,"g",null],["Beurre clarifié (ghee)",3,"c. à soupe",null],["Banane mûre",1,null,"écrasée"],["Cardamome moulue",0.5,"c. à thé",null],["Eau",150,"ml",null],["Huile ou ghee",1,"l","pour la friture"]],"steps":["Égoutter le riz et le mixer avec la banane, le sucre et un peu d’eau en pâte épaisse et lisse.","Ajouter le ghee et la cardamome; laisser reposer 1 heure.","Chauffer l’huile à 170 °C.","Verser la pâte en cercle dans l’huile avec un sac à poche ou à la main.","Frire 1 à 2 minutes par face jusqu’à coloration dorée et égoutter."],"photo":null},{"slug":"yomari-katmandou","country":"NP","place":{"slug":"np-kathmandu","name":"Katmandou","type":"city","lat":27.7172,"lng":85.324,"summary":"Capitale du Népal et cœur de la culture newar, patrie du yomari et du chatamari."},"original":"Yomari","title":"Yomari de Katmandou (bouchées de riz fourrées à la mélasse et au sésame)","en":"Kathmandu yomari (rice dumplings with molasses and sesame)","es":"Yomari de Katmandú (bolitas de arroz con melaza y sésamo)","desc":"Bouchées newar en forme de figue, en pâte de riz cuite à la vapeur, fourrées de chaku (mélasse) et de sésame pour la fête Yomari Punhi.","cat":"Dessert","diff":"hard","prep":45,"cook":20,"serv":6,"ing":[["Farine de riz",300,"g",null],["Eau chaude",250,"ml",null],["Mélasse ou sucre de canne complet",150,"g",null],["Graines de sésame",60,"g","grillées et moulues"],["Noix de coco râpée",30,"g","facultatif"],["Ghee",1,"c. à soupe",null]],"steps":["Faire fondre la mélasse avec le ghee, ajouter sésame et coco; laisser tiédir.","Pétrir la farine avec l’eau chaude en pâte souple.","Former une boule, la creuser en cône avec les doigts huilés.","Remplir de garniture et refermer en pointe allongée.","Cuire 15 à 20 minutes à la vapeur et servir tiède."],"photo":null},{"slug":"aloo-tama","country":"NP","original":"Aloo tama","title":"Aloo tama népalais (pommes de terre, pousses de bambou et haricots)","en":"Nepali aloo tama (potato, bamboo shoot and bean curry)","es":"Aloo tama nepalí (curry de patata, bambú y frijoles)","desc":"Curry acidulé de pousses de bambou fermentées, pommes de terre et haricots à œil noir, spécialité népalaise.","cat":"Plat principal","diff":"easy","prep":15,"cook":40,"serv":4,"ing":[["Pousses de bambou (fermentées ou en conserve)",250,"g",null],["Pommes de terre",3,null,"en cubes"],["Haricots à œil noir cuits",200,"g",null],["Tomates",2,null,"en dés"],["Oignon",1,null,"haché"],["Ail et gingembre",1,"c. à soupe","pilés"],["Curcuma, cumin et coriandre",2,"c. à thé",null],["Fenugrec",0.5,"c. à thé",null],["Huile de moutarde",3,"c. à soupe",null],["Sel",1,"c. à thé",null]],"steps":["Faire grésiller le fenugrec dans l’huile, ajouter oignon, ail et gingembre.","Ajouter les épices, puis les tomates; cuire 5 minutes.","Ajouter pommes de terre et pousses de bambou; bien enrober.","Couvrir de 600 ml d’eau et cuire 20 minutes.","Ajouter les haricots, saler, mijoter 10 minutes et servir avec du riz."],"photo":null},{"slug":"chapli-kebab-peshawar","country":"PK","place":{"slug":"pk-peshawar","name":"Peshawar","type":"city","lat":34.0151,"lng":71.5249,"summary":"Ville de Khyber Pakhtunkhwa, célèbre pour le chapli kebab et le bazar Qissa Khwani."},"original":"Chapli kebab","title":"Chapli kebab de Peshawar (galettes de bœuf épicées à la tomate)","en":"Peshawari chapli kebab","es":"Chapli kebab de Peshawar 